#include <iostream>
#include <stdexcept>
#include <string>

class ResourceGuard {
    std::string name;
public:
    explicit ResourceGuard(std::string n) : name(std::move(n)) {
        std::cout << "Acquired: " << name << "\n";
    }
    ~ResourceGuard() {
        std::cout << "Cleaned up: " << name << "\n";
    }
};

void function3() {
    ResourceGuard guard3("function3_resource");
    std::cout << "In function 3 - throwing runtime_error\n";
    throw std::runtime_error("failure in function3");
}

void function2() {
    ResourceGuard guard2("function2_resource");
    std::cout << "function2 calls function3\n";
    try {
        function3();
    } catch (const std::exception &e) {
        std::cout << "function2 partially caught: " << e.what() << ", rethrowing...\n";
        throw; // rethrow
    }
}

void function1() {
    ResourceGuard guard1("function1_resource");
    std::cout << "function1 calls function2\n";
    function2();
}

int main() {
    try {
        std::cout << "main calls function1\n";
        function1();
    } catch (const std::runtime_error &e) {
        std::cout << "Exception handled in main: " << e.what() << "\n";
    }
    std::cout << "Program continues normally after main catch\n";
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>

class Member {
    std::string name;
public:
    explicit Member(std::string n) : name(std::move(n)) {
        std::cout << "Member initialized: " << name << "\n";
    }
    ~Member() noexcept {
        std::cout << "Member destroyed: " << name << "\n";
    }
};

class Device {
    Member mem1;
    Member mem2;
public:
    Device(int setting) : mem1("Subsystem_1"), mem2("Subsystem_2") {
        std::cout << "Constructing Device with setting " << setting << "\n";
        if (setting < 0) {
            throw std::invalid_argument("Negative setting not allowed");
        }
        std::cout << "Device constructed successfully\n";
    }
    ~Device() noexcept {
        std::cout << "Device destructor called\n";
    }
};

// A non-throwing helper marked noexcept
bool isValidSetting(int s) noexcept {
    return s >= 0;
}

int main() {
    std::cout << "isValidSetting(10): " << std::boolalpha << isValidSetting(10) << "\n";

    try {
        std::cout << "Attempting to construct Device with setting -1...\n";
        Device dev(-1);
    } catch (const std::invalid_argument &e) {
        std::cout << "Caught constructor failure: " << e.what() << "\n";
    }

    std::cout << "Execution safely finished.\n";
    return 0;
}
